const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var cambodia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'));
  var geometry = cambodia.geometry();

  var startDate = '2014-01-01';
  var endDate = '2018-01-01';  // Cover 2014-2017 inclusive

  // Helper function to get fire count for a specific month
  async function getFireCount(month) {
    var collection = ee.ImageCollection('MODIS/006/MOD14A1')
      .filterDate(startDate, endDate)
      .filter(ee.Filter.calendarRange(month, month, 'month'))
      .filterBounds(geometry);

    // Check if collection is empty
    var size = collection.size().getInfo();
    if (size === 0) {
      // Try alternative Aqua MODIS collection
      collection = ee.ImageCollection('MODIS/006/MYD14A1')
        .filterDate(startDate, endDate)
        .filter(ee.Filter.calendarRange(month, month, 'month'))
        .filterBounds(geometry);
      size = collection.size().getInfo();
      if (size === 0) return null;
    }

    // Create binary fire mask (FireMask values 6-9 = fire)
    var fireMask = collection.map(function(image) {
      var fire = image.select('FireMask').gte(6).and(image.select('FireMask').lte(9));
      return fire.rename('fire').set('system:time_start', image.get('system:time_start'));
    });

    // Sum all fire detections
    var totalFire = fireMask.sum();

    // Count fire pixels over Cambodia
    var result = totalFire.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }).get('fire');

    var count = result.getInfo();

    // Check for no valid pixels
    var pixelCheck = totalFire.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }).get('fire').getInfo();

    return {count: count, pixelCount: pixelCheck, collectionSize: size};
  }

  // 2. Get fire counts for February (month=2) and October (month=10)
  var febStats = await getFireCount(2);
  var octStats = await getFireCount(10);

  // 3. Check for data issues
  if (febStats === null || octStats === null) {
    console.log(`February data: ${febStats ? 'Available' : 'Missing'}`);
    console.log(`October data: ${octStats ? 'Available' : 'Missing'}`);
    console.log('<answer>C1</answer>');
    return;
  }

  console.log(`February (2014-2017): ${febStats.collectionSize} images, Fire pixels: ${febStats.count}`);
  console.log(`October (2014-2017): ${octStats.collectionSize} images, Fire pixels: ${octStats.count}`);

  // Check for no valid pixels
  if (febStats.pixelCount === 0 || octStats.pixelCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for calculation failures
  if (febStats.count === null || octStats.count === null || 
      isNaN(febStats.count) || isNaN(octStats.count)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 4. Compare and output final answer
  if (febStats.count > octStats.count) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
